'z_followup_ut': "df.assign(g=df.group.str.strip()).dropna(subset=['followup_7d']).pipe(lambda t: pd.Series({u: round((lambda s: (s.loc[s.g == '实验组', 'followup_7d'].mean() - s.loc[s.g == '对照组', 'followup_7d'].mean()) / np.sqrt(s.followup_7d.mean() * (1 - s.followup_7d.mean()) * (1 / (s.g == '实验组').sum() + 1 / (s.g == '对照组').sum())))(t[t.user_type == u]), 2) for u in ['新用户', '老用户']}))",
}
for k,c in tests.items():
    print('='*70); print(k)
    try:
        print(eval(c, {'pd':pd,'np':np}, {'df':df}))
    except Exception as e:
        print('ERR', repr(e))
